import Foundation

/// Writes a week's review from the records alone: the meetings and what they
/// decided, the tasks finished and coming due, and the journal. Nothing is
/// generated by a model, so every line can be traced to a record.
enum WeeklyReviewBuilder {
  struct Input {
    var week: DateInterval
    var meetings: [Meeting]
    var tasks: [MemoraTask]
    var entries: [LifeLogEntry]
    var spaceNames: [UUID: String]
  }

  static func title(for week: DateInterval) -> String {
    "週報 \(shortDay(week.start))〜\(shortDay(week.end.addingTimeInterval(-1)))"
  }

  /// 9/27, whatever the device's region, so titles read the same everywhere.
  private static func shortDay(_ date: Date) -> String {
    let parts = Calendar.current.dateComponents([.month, .day], from: date)
    return "\(parts.month ?? 0)/\(parts.day ?? 0)"
  }

  /// 9/27（土）
  private static func dayWithWeekday(_ date: Date) -> String {
    let symbols = ["日", "月", "火", "水", "木", "金", "土"]
    let weekday = Calendar.current.component(.weekday, from: date)
    return "\(shortDay(date))（\(symbols[(weekday - 1) % 7])）"
  }

  /// The review's markdown, or nil when nothing happened that week.
  static func markdown(_ input: Input) -> String? {
    let week = input.week
    let meetings = input.meetings
      .filter { $0.createdAt >= week.start && $0.createdAt < week.end }
      .sorted { $0.createdAt < $1.createdAt }
    let finished = input.tasks
      .filter { $0.isCompleted && ($0.completedAt.map { $0 >= week.start && $0 < week.end } ?? false) }
    let nextWeekEnd = Calendar.current.date(byAdding: .day, value: 7, to: week.end) ?? week.end
    let nextWeek = DateInterval(start: week.end, end: nextWeekEnd)
    let comingDue = input.tasks
      .filter { !$0.isCompleted && ($0.dueDate.map { $0 >= nextWeek.start && $0 < nextWeek.end } ?? false) }
      .sorted { ($0.dueDate ?? .distantFuture) < ($1.dueDate ?? .distantFuture) }
    let overdue = input.tasks
      .filter { !$0.isCompleted && ($0.dueDate.map { $0 < week.end } ?? false) }
      .sorted { ($0.dueDate ?? .distantPast) < ($1.dueDate ?? .distantPast) }
    let entries = input.entries.filter { $0.occurredAt >= week.start && $0.occurredAt < week.end }
    let addedTasks = meetings.reduce(0) { count, meeting in
      count + input.tasks.filter { $0.meetingID == meeting.id }.count
    }

    guard !meetings.isEmpty || !finished.isEmpty || !entries.isEmpty else { return nil }

    var lines: [String] = []
    let hours = meetings.reduce(0) { $0 + $1.duration } / 3600
    lines.append("## 概要")
    if !meetings.isEmpty {
      lines.append("- 会議 \(meetings.count)件（合計 \(hours.formatted(.number.precision(.fractionLength(0...1))))時間）")
    }
    if addedTasks > 0 {
      lines.append("- 会議から生まれたタスク \(addedTasks)件")
    }
    if !finished.isEmpty {
      lines.append("- 完了したタスク \(finished.count)件")
    }
    if !entries.isEmpty {
      lines.append("- ジャーナルの記録 \(entries.count)件")
    }

    if !meetings.isEmpty {
      lines.append("")
      lines.append("## 会議")
      for meeting in meetings {
        var heading = "### \(dayWithWeekday(meeting.createdAt)) \(meeting.displayTitle)"
        if let spaceID = meeting.spaceID, let name = input.spaceNames[spaceID] {
          heading += "（\(name)）"
        }
        lines.append(heading)
        let preview = meeting.summaryPreview.trimmingCharacters(in: .whitespacesAndNewlines)
        if !preview.isEmpty {
          lines.append(String(preview.prefix(160)))
        }
        for decision in meeting.decisions.prefix(4) {
          lines.append("- 決定: \(decision)")
        }
      }
    }

    if !finished.isEmpty {
      lines.append("")
      lines.append("## 完了したタスク")
      lines += finished.prefix(20).map { "- \($0.title)" }
    }

    if !comingDue.isEmpty {
      lines.append("")
      lines.append("## 来週が期限")
      lines += comingDue.prefix(20).map { task in
        let due = task.dueDate.map(dayWithWeekday) ?? ""
        return "- \(task.title)（\(due)\(task.assignee.map { "・\($0)" } ?? "")）"
      }
    }

    if !overdue.isEmpty {
      lines.append("")
      lines.append("## 期限を過ぎたタスク")
      lines += overdue.prefix(20).map { task in
        let due = task.dueDate.map(shortDay) ?? ""
        return "- \(task.title)（期限 \(due)）"
      }
    }

    if !entries.isEmpty {
      lines.append("")
      lines.append("## ジャーナル")
      let places = Array(Set(entries.compactMap { $0.kind == .location ? $0.locationName : nil }.filter { !$0.isEmpty })).sorted()
      if !places.isEmpty {
        lines.append("- 訪れた場所: \(places.prefix(10).joined(separator: "、"))")
      }
      let memos = entries.filter { $0.kind == .memo }
      for memo in memos.prefix(8) {
        lines.append("- **\(shortDay(memo.occurredAt)) \(memo.title)**")
        if !memo.summary.isEmpty {
          lines.append("  \(memo.summary.prefix(240))")
        }
      }
      let photos = entries.filter { $0.kind == .photo }.count
      if photos > 0 {
        lines.append("- 写真 \(photos)枚")
      }
    }

    return lines.joined(separator: "\n")
  }
}
